/*
 Problem: 3534. Path Existence Queries in a Graph II
 Language: cpp
 Runtime: 149 ms (79.68%)
 Memory: 357 MB (65.77%)
 Tags: Array, Two Pointers, Binary Search, Dynamic Programming, Greedy, Bit Manipulation, Graph Theory, Sorting
*/
class Solution {
public:
    vector<int> pathExistenceQueries(int n, vector<int>& nums, int maxDiff, vector<vector<int>>& queries) {
        vector<pair<int, int>> a;
        a.reserve(n);

        for (int i = 0; i < n; ++i)
            a.emplace_back(nums[i], i);

        sort(a.begin(), a.end());

        vector<int> pos(n);
        for (int i = 0; i < n; ++i)
            pos[a[i].second] = i;

        vector<int> comp(n);
        int id = 0;
        for (int i = 1; i < n; ++i) {
            if (a[i].first - a[i - 1].first > maxDiff)
                ++id;
            comp[i] = id;
        }

        vector<int> right(n);
        for (int l = 0, r = 0; l < n; ++l) {
            while (r + 1 < n && a[r + 1].first - a[l].first <= maxDiff)
                ++r;
            right[l] = r;
        }

        constexpr int LOG = 20;
        vector<vector<int>> up(LOG, vector<int>(n));

        for (int i = 0; i < n; ++i)
            up[0][i] = right[i];

        for (int k = 1; k < LOG; ++k)
            for (int i = 0; i < n; ++i)
                up[k][i] = up[k - 1][up[k - 1][i]];

        vector<int> ans;
        ans.reserve(queries.size());

        for (auto &q : queries) {
            int u = pos[q[0]];
            int v = pos[q[1]];

            if (u > v)
                swap(u, v);

            if (comp[u] != comp[v]) {
                ans.emplace_back(-1);
                continue;
            }

            if (u == v) {
                ans.emplace_back(0);
                continue;
            }

            int cur = u, step = 0;

            for (int k = LOG - 1; k >= 0; --k)
                if (up[k][cur] < v) {
                    cur = up[k][cur];
                    step += 1 << k;
                }

            ans.emplace_back(step + 1);
        }

        return ans;
    }
};
